import time
from .exceptions import (TimeoutError, SnapshotError, ConnectionError)
from .session import Session, AnonymousSession
import logging
import requests.exceptions


class SessionHandler(object):
    def __init__(self):
        self.session = None

    # TODO: remove
    @property
    def url(self):
        return self._get_complete_url("")

    def create_session(self, base_url, port=None, username=None,
                       password=None):
        """ Create new session. If authentication is required then username and
        password should be provided, otherwise Session without authentication
        will be established.

        :base_url: Base URL as str, it can contain protocol (http, https) eg.:
            'http://127.0.0.1', if it was not specified, then 'https' is use
            by default.
        :username: user name as (str), if authentication is not needed then it
            can be None, None is default value
        :password: user password as (str), if authentication is not needed then
            it can be None, None is default value
        :port: if no port specified then it will be handled by requests
        library, if one wants to send requests through custom port it can
        provided as (str) or (int)
        """
        kwargs = dict(base_url=base_url, port=port)
        if username is not None and password is not None:
            kwargs['username'] = username
            kwargs['password'] = password
            self.session = Session(**kwargs)
        else:
            self.session = AnonymousSession(**kwargs)

    def teardown_session(self, timeout=10):
        if not self.session:
            return

        try:
            self._teardown_session_with_retry(timeout)
        finally:
            self.session = None

    def _teardown_session_with_retry(self, timeout):
        start = time.time()
        while time.time() - start < timeout:
            try:
                self.session.teardown(timeout=min(5, timeout))
                self.session.close()
                break
            except (requests.exceptions.ConnectionError,
                    requests.exceptions.ReadTimeout) as e:
                logging.warning(str(e))
            time.sleep(1)

    def __del__(self):
        self.teardown_session()

    def send_request(self, url, method='GET', headers=None, **kwargs):
        """
        Send request using python's request library. Except defined arguments
        any named argument described in request library for used method
        can be used. If no header defined for POST and PUT methods, then default
        json header will be used.
        :param url: REST uri, only ending needed, full url will be created from
        OAM ip defined during session creation
        :param method: REST GET by default, available methods are: GET, POST, PUT
        :param headers: headers dictionary which should be attached to request
        """
        if self.session:
            return self.session.send_request(url,
                                             method=method,
                                             headers=headers,
                                             **kwargs)
        else:
            raise ConnectionError('Connection has not been initalized.')

    def _is_alive(self):
        """ Check if session is available

        :return: boolean
        """
        return self.session is not None

    # TODO: methods reporting errors should not be in session handler
    def report_snapshot_error(self, json):
        if 'error' in json:
            raise SnapshotError(json['error']['errorCode'])

    def report_snapshot_timeout_error(self):
        raise TimeoutError("Request has timed out")
